import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Рейды и платные события","description":"","frontmatter":{"pageId":"players/raids-incidents","contentRevision":7},"headers":[],"relativePath":"ru/players/raids-incidents.md","filePath":"ru/players/raids-incidents.md"}'),o={name:"ru/players/raids-incidents.md"};function n(s,a,l,d,p,c){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="реиды-и-платные-события" tabindex="-1">Рейды и платные события <a class="header-anchor" href="#реиды-и-платные-события" aria-label="Permalink to &quot;Рейды и платные события&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Перед рейдом выбери цель, пешек и режим. Snapshot-режим использует копии; реальный режим рискует настоящими пешками. Проверь подтверждение, предупреждение защитнику и правила добычи. Предупреждённый рейд даёт защитнику время (по умолчанию 60 000 тиков); мгновенный сокращает допустимую добычу вдвое.</p><p>Платные события заказываются через доступный серверный каталог. Цена и предупреждение зависят от вида и интенсивности. Сервер проверяет мирный режим, союз, защиту новичка, cooldown и очередь цели. Отмена и отказ обрабатываются через эскроу, а не ручную повторную выдачу.</p><p>Открывай результат операции и почту после рейда: возврат собственных пешек и разрешённая добыча отличаются от произвольного сохранения копии карты.</p><h2 id="raid-choice" tabindex="-1">Как выбрать риск рейда до отправки? <a class="header-anchor" href="#raid-choice" aria-label="Permalink to &quot;Как выбрать риск рейда до отправки? {#raid-choice}&quot;">​</a></h2><p>У каравана или капсул на чужом поселении выбери рейд и состав участников. <strong>Real</strong> забирает настоящих пешек: выжившие возвращаются с ранами и инвентарём, пленные остаются защитнику. <strong>Copies</strong> не забирает оригиналов, но уменьшает добычу. <strong>Warned</strong> даёт защитнику игровые сутки подготовки; <strong>Instant</strong> уменьшает добычу. Предельная добыча дополнительно ограничена богатством цели и настройками сервера.</p><p>Защитник играет в своей карте, когда входит; обычный рейд не требует одновременного online. Проверь статус во вкладке рейдов и результаты в почте. Снаряжение, принесённое реальными рейдерами, не становится лимитированной добычей; копии не переносят его обратно как реальные предметы.</p><p>Перед отправкой копии работника аванпоста игра сохраняет его текущее состояние. Копия несёт UUID работника как зеркало без права владения. В реальном рейде защитник получает захваченного работника одной защищённой посылкой. Принятая квитанция закрепляет нового владельца, а пешка сохраняет статус пленника.</p><p>Когда рейдер уходит с карты, его состояние попадает в результат рейда. После подготовки этого результата игра удаляет оставшийся мировой объект пешки перед сохранением, чтобы он не сохранялся вместе с возвращённой пешкой.</p><p>Мирный режим закрывает рейды в обе стороны. Его выключение по умолчанию занимает 24 часа; повторная галочка сохраняет защиту. Новички, бедные колонии и союзники защищаются отдельными серверными правилами. Блокировка чата не выдаёт такую защиту.</p><h2 id="incident-order" tabindex="-1">Платные события: заказ, неизвестный ответ и возврат <a class="header-anchor" href="#incident-order" aria-label="Permalink to &quot;Платные события: заказ, неизвестный ответ и возврат {#incident-order}&quot;">​</a></h2><p>Экономика → «События»: выбери цель, событие из каталога, уровень и капсулы, если доступны. Прочти рассчитанную сервером цену, затем подтверди. У hostile уровня 1 — половина базовых threat points, 2 — обычные, 3 — полуторные, 4 — двойные. Hostile уровней 3–4 предупреждаются за половину игрового дня.</p><p>Враждебные/погодные события подчиняются защитам и cooldown рейдов; дружественные имеют отдельный короткий cooldown. По умолчанию очередь цели — два события. Если событие не смогло выполниться, истекло без входа цели или отменено администратором, фонд возвращается. За выполненное событие цель деньги не получает.</p><p>При неизвестном ответе используй «Retry original order». Не меняй цель и не покупай то же событие повторно: локально сохранённое намерение должно сначала разрешиться. «Мои заказы» показывает результат; угроза от ожидающего hostile также закрывает экспорт товаров.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию: 10 рейдеров, 1 активный рейд, cooldown 8 ч и 24 ч на пару, защита новичка 3 дня, минимум богатства 20 000, добыча 10% с потолком 5 000, похищения выключены. Отключение мирного режима вступает через 24 ч. Союзники не могут заказывать вредные события друг другу.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: живая карта</a></li><li><a href="./visits">Визиты и магазин</a></li><li><a href="./../admins/gameplay-policy">Игровая политика сервера</a></li></ul>',20)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
